@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
  + isCompleted : boolean
}

Organizer "1..*" -- "1" Event : organizes
Organizer "0..*" -- "0..*" Event : attends
Event "*" -- "1" EventType : is of type
Event "*" -- "1" Location : takes place at
Event "1" *-- "*" Task : has checklist
Event "1" -- "0..*" Attendee : invites

Attendee "0..1" -- "0..*" Event : attends

Task "0..*" -- "0..1" Attendee : assigned to

Task "*" -- "1" Task : available for next event

@enduml

